  1022  /*
  1023   * Expand any embedded %h (host) escapes in the given path and makes
  1024   * a relative path fully-qualified based on the current sudoers file.
  1025   * Returns a reference-counted string.
  1026   */
  1027  static char *
  1028  expand_include(const char *opath, size_t olen)
  1029  {
  1030      const char *cp, *ep;
  1031      char *path, *pp;
  1032      int dirlen = 0, len;
  1033      size_t shost_len = 0;
  1034      bool subst = false;
  1035      debug_decl(expand_include, SUDOERS_DEBUG_PARSER);
  1036
  1037      /* Strip double quotes if present. */
  1038      if (*opath == '"') {
  1039          opath++;
  1040          olen -= 2;
  1041      }
  1042
  1043      /* Relative paths are located in the same dir as the sudoers file. */
  1044      if (*opath != '/') {
  1045          char *dirend = strrchr(sudoers, '/');
  1046          if (dirend != NULL)
  1047              dirlen = (int)(dirend - sudoers) + 1;
  1048      }
  1049
  1050      len = olen;
  1051      for (cp = opath, ep = opath + olen; cp < ep; cp++) {
  1052          if (cp[0] == '%' && cp[1] == 'h') {
  1053              shost_len = strlen(user_shost);
  1054              len += shost_len - 2;
  1055              subst = true;
  1056          }
  1057      }
  1058
  1059      /* Make a copy of the fully-qualified path and return it. */
  1060      path = pp = rcstr_alloc(len + dirlen);
  1061      if (path == NULL) {
  1062          sudo_warnx(U_("%s: %s"), __func__, U_("unable to allocate memory"));
  1063          sudoerserror(NULL);
  1064          debug_return_str(NULL);
  1065      }
  1066      if (dirlen) {
  1067          memcpy(path, sudoers, dirlen);
  1068          pp += dirlen;
  1069      }
  1070      if (subst) {
  1071          /* substitute for %h */
  1072          cp = opath;
  1073          while (cp < ep) {
  1074              if (cp[0] == '%' && cp[1] == 'h') {
  1075                  memcpy(pp, user_shost, shost_len);
  1076                  pp += shost_len;
  1077                  cp += 2;
  1078                  continue;
  1079              }
  1080              *pp++ = *cp++;
  1081          }
  1082          *pp = '\0';
  1083      } else {
  1084          memcpy(pp, opath, len);
  1085          pp[len] = '\0';
  1086      }
  1087
  1088      debug_return_str(path);
  1089  }
